+package cue
+
+import (
+	_ "embed"
+	"encoding/json"
+	"errors"
+	"fmt"
+	"io"
+	"os"
+	"sort"
+	"strconv"
+	"strings"
+
+	"cuelang.org/go/cue"
+	"cuelang.org/go/cue/cuecontext"
+	cueerror "cuelang.org/go/cue/errors"
+	cueyaml "cuelang.org/go/encoding/yaml"
+	yaml "gopkg.in/yaml.v3"
+)
+
+const (
+	jsonFormat = "json"
+	textFormat = "text"
+)
+
+var (
+	//go:embed flipt.cue
+	cueFile             []byte
+	ErrValidationFailed = errors.New("validation failed")
+)
+
+// Location identifies a position in the original YAML input.
+type Location struct {
+	File   string `json:"file,omitempty"`
+	Line   int    `json:"line"`
+	Column int    `json:"column"`
+}
+
+// Error describes a single validation failure.
+type Error struct {
+	Path     string   `json:"path"`
+	Message  string   `json:"message"`
+	Location Location `json:"location"`
+}
+
+// Result contains every error found while validating a YAML document.
+type Result struct {
+	Errors []Error `json:"errors"`
+}
+
+// FeaturesValidator validates YAML feature definitions against the embedded CUE schema.
+type FeaturesValidator struct {
+	cue *cue.Context
+	v   cue.Value
+}
+
+// NewFeaturesValidator compiles the embedded schema once for repeated validation.
+func NewFeaturesValidator() (*FeaturesValidator, error) {
+	cctx := cuecontext.New()
+	v := cctx.CompileBytes(cueFile)
+	if err := v.Err(); err != nil {
+		return nil, fmt.Errorf("compile features schema: %w", err)
+	}
+
+	return &FeaturesValidator{cue: cctx, v: v}, nil
+}
+
+// Validate checks a YAML document and returns all of its validation errors.
+// Invalid input returns a populated Result together with ErrValidationFailed.
+func (validator *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
+	result := Result{Errors: make([]Error, 0)}
+
+	f, err := cueyaml.Extract(file, b)
+	if err != nil {
+		result.Errors = append(result.Errors, Error{
+			Message:  err.Error(),
+			Location: yamlSyntaxLocation(file, err),
+		})
+		return result, ErrValidationFailed
+	}
+
+	yv := validator.cue.BuildFile(f, cue.Scope(validator.v))
+	yv = validator.v.Unify(yv)
+	if err := yv.Validate(); err != nil {
+		result.Errors = validationErrors(file, b, err)
+		return result, ErrValidationFailed
+	}
+
+	return result, nil
+}
+
+// ValidateBytes validates YAML without a filename.
+func ValidateBytes(b []byte) error {
+	validator, err := NewFeaturesValidator()
+	if err != nil {
+		return err
+	}
+
+	_, err = validator.Validate("", b)
+	return err
+}
+
+type sourceLocation struct {
+	key   Location
+	value Location
+}
+
+func pathKey(path []string) string {
+	return strings.Join(path, "\x00")
+}
+
+// CUE's YAML conversion can shift columns, particularly for fields inside a
+// sequence. Read the YAML node positions directly to report source coordinates.
+func yamlSourceLocations(file string, b []byte) map[string]sourceLocation {
+	locations := make(map[string]sourceLocation)
+	var document yaml.Node
+	if err := yaml.Unmarshal(b, &document); err != nil {
+		return locations
+	}
+
+	var walk func(*yaml.Node, []string)
+	walk = func(node *yaml.Node, path []string) {
+		if node == nil {
+			return
+		}
+
+		key := pathKey(path)
+		current := locations[key]
+		if current.value.Line == 0 {
+			current.value = Location{File: file, Line: node.Line, Column: node.Column}
+			locations[key] = current
+		}
+
+		switch node.Kind {
+		case yaml.DocumentNode:
+			for _, child := range node.Content {
+				walk(child, path)
+			}
+		case yaml.MappingNode:
+			for i := 0; i+1 < len(node.Content); i += 2 {
+				label, value := node.Content[i], node.Content[i+1]
+				childPath := append(append([]string(nil), path...), label.Value)
+				locations[pathKey(childPath)] = sourceLocation{
+					key:   Location{File: file, Line: label.Line, Column: label.Column},
